const std = @import("std");

const IntPoint = struct {
    x: i32 = 0,
    y: i32 = 0,
};

const IntSize = struct {
    width: i32 = 0,
    height: i32 = 0,

    fn eql(self: IntSize, other: IntSize) bool {
        return self.width == other.width and self.height == other.height;
    }
};

const IntRect = struct {
    origin: IntPoint = .{},
    size: IntSize = .{},

    fn isEmpty(self: IntRect) bool {
        return self.size.width <= 0 or self.size.height <= 0;
    }
};

const FloatPoint = struct {
    x: f64 = 0,
    y: f64 = 0,
};

const FramesPerSecond = f64;
const DisplayID = u64;
const PlatformPaintContextPtr = ?*anyopaque;
const AsyncReplyID = u64;
const Seconds = u64;

const MonotonicTime = struct {
    nanoseconds: i128,

    fn now() MonotonicTime {
        return .{ .nanoseconds = std.time.nanoTimestamp() };
    }
};

const Region = struct {
    allocator: std.mem.Allocator,
    rects: std.ArrayList(IntRect),

    fn init(allocator: std.mem.Allocator) Region {
        return .{ .allocator = allocator, .rects = std.ArrayList(IntRect).init(allocator) };
    }

    fn deinit(self: *Region) void {
        self.rects.deinit();
    }

    fn unite(self: *Region, rect: IntRect) !void {
        if (!rect.isEmpty())
            try self.rects.append(rect);
    }

    fn subtract(self: *Region, rect: IntRect) void {
        if (rect.isEmpty())
            return;
        var index: usize = 0;
        while (index < self.rects.items.len) {
            const candidate = self.rects.items[index];
            if (candidate.origin.x >= rect.origin.x and candidate.origin.y >= rect.origin.y and candidate.origin.x + candidate.size.width <= rect.origin.x + rect.size.width and candidate.origin.y + candidate.size.height <= rect.origin.y + rect.size.height) {
                _ = self.rects.orderedRemove(index);
                continue;
            }
            index += 1;
        }
    }

    fn assignRect(self: *Region, rect: IntRect) !void {
        self.rects.clearRetainingCapacity();
        try self.unite(rect);
    }
};

const Preferences = struct {
    accelerated_compositing_enabled: bool = true,
    force_compositing_mode: bool = false,

    fn acceleratedCompositingEnabled(self: *const Preferences) bool {
        return self.accelerated_compositing_enabled;
    }

    fn forceCompositingMode(self: *const Preferences) bool {
        return self.force_compositing_mode;
    }
};

const LegacyMainFrameProcess = struct {
    nominal_frames_per_second: FramesPerSecond = 60,

    fn nominalFramesPerSecondForDisplay(self: *const LegacyMainFrameProcess, _: DisplayID) FramesPerSecond {
        return self.nominal_frames_per_second;
    }
};

const WebPageProxy = struct {
    view_visible: bool = true,
    running_process: bool = true,
    view_size: IntSize = .{},
    device_scale_factor: f64 = 1,
    display_id: ?DisplayID = null,
    preferences_value: Preferences = .{},
    legacy_main_frame_process_value: LegacyMainFrameProcess = .{},
    accelerated_compositing_mode: bool = false,
    last_damage_region: ?Region = null,

    fn deinit(self: *WebPageProxy) void {
        if (self.last_damage_region) |*region|
            region.deinit();
    }

    fn isViewVisible(self: *const WebPageProxy) bool {
        return self.view_visible;
    }

    fn hasRunningProcess(self: *const WebPageProxy) bool {
        return self.running_process;
    }

    fn viewSize(self: *const WebPageProxy) IntSize {
        return self.view_size;
    }

    fn deviceScaleFactor(self: *const WebPageProxy) f64 {
        return self.device_scale_factor;
    }

    fn displayID(self: *const WebPageProxy) ?DisplayID {
        return self.display_id;
    }

    fn preferences(self: *const WebPageProxy) *const Preferences {
        return &self.preferences_value;
    }

    fn legacyMainFrameProcess(self: *const WebPageProxy) *const LegacyMainFrameProcess {
        return &self.legacy_main_frame_process_value;
    }

    fn enterAcceleratedCompositingMode(self: *WebPageProxy, _: LayerTreeContext) void {
        self.accelerated_compositing_mode = true;
    }

    fn exitAcceleratedCompositingMode(self: *WebPageProxy) void {
        self.accelerated_compositing_mode = false;
    }

    fn updateAcceleratedCompositingMode(self: *WebPageProxy, _: LayerTreeContext) void {}

    fn setViewNeedsDisplay(self: *WebPageProxy, damage_region: *const Region) !void {
        if (self.last_damage_region) |*region|
            region.deinit();
        var copied_region = Region.init(damage_region.allocator);
        errdefer copied_region.deinit();
        try copied_region.rects.appendSlice(damage_region.rects.items);
        self.last_damage_region = copied_region;
    }
};

const WebProcessState = enum {
    launching,
    running,
    terminated,
};

const Connection = struct {
    has_connection: bool = true,

    fn waitForAndDispatchImmediately(self: *Connection, _: u64, _: u64) bool {
        return self.has_connection;
    }

    fn takeAsyncReplyHandler(_: *Connection, _: AsyncReplyID) ?AsyncReplyHandler {
        return null;
    }
};

const WebProcessProxy = struct {
    connection_value: Connection = .{},
    process_state: WebProcessState = .running,

    fn hasConnection(self: *const WebProcessProxy) bool {
        return self.connection_value.has_connection;
    }

    fn state(self: *const WebProcessProxy) WebProcessState {
        return self.process_state;
    }

    fn connection(self: *WebProcessProxy) *Connection {
        return &self.connection_value;
    }
};

const LayerTreeContext = struct {
    identifier: u64 = 0,
};

const UpdateInfo = struct {
    update_rect_bounds: IntRect = .{},
    view_size: IntSize = .{},
    device_scale_factor: f64 = 1,
    scroll_rect: IntRect = .{},
    update_rects: []const IntRect = &.{},
};

const BackingStore = struct {
    allocator: std.mem.Allocator,
    backing_size: IntSize,
    backing_device_scale_factor: f64,
    last_update: ?UpdateInfo = null,

    fn init(allocator: std.mem.Allocator, backing_size: IntSize, backing_device_scale_factor: f64) BackingStore {
        return .{
            .allocator = allocator,
            .backing_size = backing_size,
            .backing_device_scale_factor = backing_device_scale_factor,
        };
    }

    fn deinit(self: *BackingStore) void {
        if (self.last_update) |update|
            self.allocator.free(update.update_rects);
    }

    fn size(self: *const BackingStore) IntSize {
        return self.backing_size;
    }

    fn deviceScaleFactor(self: *const BackingStore) f64 {
        return self.backing_device_scale_factor;
    }

    fn paint(_: *const BackingStore, _: PlatformPaintContextPtr, _: IntRect) void {}

    fn incorporateUpdate(self: *BackingStore, update_info: UpdateInfo) !void {
        if (self.last_update) |previous_update|
            self.allocator.free(previous_update.update_rects);
        const copied_rects = try self.allocator.dupe(IntRect, update_info.update_rects);
        self.last_update = .{
            .update_rect_bounds = update_info.update_rect_bounds,
            .view_size = update_info.view_size,
            .device_scale_factor = update_info.device_scale_factor,
            .scroll_rect = update_info.scroll_rect,
            .update_rects = copied_rects,
        };
    }
};

const AsyncReplyHandler = *const fn (?*anyopaque, ?*anyopaque) void;
const CompletionHandler = *const fn () void;

const Timer = struct {
    active: bool = false,
    callback: ?*const fn (*anyopaque) void = null,
    context: ?*anyopaque = null,

    fn isActive(self: *const Timer) bool {
        return self.active;
    }

    fn startOneShot(self: *Timer, _: Seconds) void {
        self.active = true;
    }

    fn stop(self: *Timer) void {
        self.active = false;
    }
};

const DrawingMonitor = struct {
    timer: Timer = .{},
    callback: ?CompletionHandler = null,

    fn init(_: *WebPageProxy) DrawingMonitor {
        return .{};
    }

    fn deinit(self: *DrawingMonitor) void {
        if (self.callback) |callback|
            callback();
        self.stop();
    }

    fn start(self: *DrawingMonitor, callback: CompletionHandler) void {
        self.callback = callback;
        self.timer.startOneShot(0);
    }

    fn stop(self: *DrawingMonitor) void {
        self.timer.stop();
        if (self.callback) |callback| {
            self.callback = null;
            callback();
        }
    }
};

const DrawingAreaProxyCoordinatedGraphics = struct {
    allocator: std.mem.Allocator,
    page_value: ?*WebPageProxy,
    web_process_proxy_value: *WebProcessProxy,
    backing_store: ?BackingStore = null,
    discard_backing_store_timer: Timer = .{},
    discard_backing_store_deadline: ?i128 = null,
    is_backing_store_discardable: bool = false,
    is_waiting_for_did_update_geometry: bool = false,
    in_force_update: bool = false,
    last_sent_size: IntSize = .{},
    layer_tree_context: LayerTreeContext = .{},
    drawing_monitor: ?DrawingMonitor = null,
    identifier_value: u64 = 0,

    fn create(allocator: std.mem.Allocator, page: *WebPageProxy, web_process_proxy: *WebProcessProxy) DrawingAreaProxyCoordinatedGraphics {
        return .{
            .allocator = allocator,
            .page_value = page,
            .web_process_proxy_value = web_process_proxy,
        };
    }

    fn deinit(self: *DrawingAreaProxyCoordinatedGraphics) void {
        if (self.isInAcceleratedCompositingMode())
            self.exitAcceleratedCompositingMode();
        if (self.backing_store) |*backing_store|
            backing_store.deinit();
        if (self.drawing_monitor) |*drawing_monitor|
            drawing_monitor.deinit();
    }

    fn page(self: *DrawingAreaProxyCoordinatedGraphics) ?*WebPageProxy {
        return self.page_value;
    }

    fn webProcessProxy(self: *DrawingAreaProxyCoordinatedGraphics) *WebProcessProxy {
        return self.web_process_proxy_value;
    }

    fn identifier(self: *const DrawingAreaProxyCoordinatedGraphics) u64 {
        return self.identifier_value;
    }

    fn size(self: *DrawingAreaProxyCoordinatedGraphics) IntSize {
        if (self.page()) |page|
            return page.viewSize();
        return .{};
    }

    fn isInAcceleratedCompositingMode(self: *const DrawingAreaProxyCoordinatedGraphics) bool {
        return self.layer_tree_context.identifier != 0;
    }

    fn processTimers(self: *DrawingAreaProxyCoordinatedGraphics) void {
        if (self.discard_backing_store_deadline) |deadline| {
            if (std.time.nanoTimestamp() >= deadline) {
                self.discard_backing_store_deadline = null;
                self.discard_backing_store_timer.stop();
                self.discardBackingStore();
            }
        }
    }

    fn paint(self: *DrawingAreaProxyCoordinatedGraphics, cr: PlatformPaintContextPtr, rect: IntRect, unpainted_region: *Region) !void {
        try unpainted_region.assignRect(rect);

        if (self.isInAcceleratedCompositingMode())
            return;

        if (self.backing_store == null and !self.forceUpdateIfNeeded())
            return;

        if (self.backing_store) |*backing_store| {
            backing_store.paint(cr, rect);
            unpainted_region.subtract(.{ .origin = .{}, .size = backing_store.size() });
        }

        self.discardBackingStoreSoon();
    }

    fn forceUpdateIfNeeded(self: *DrawingAreaProxyCoordinatedGraphics) bool {
        std.debug.assert(!self.isInAcceleratedCompositingMode());

        if (!self.webProcessProxy().hasConnection())
            return false;

        if (self.webProcessProxy().state() == .launching)
            return false;

        if (self.is_waiting_for_did_update_geometry)
            return false;

        const page = self.page() orelse return false;
        if (!page.isViewVisible())
            return false;

        self.in_force_update = true;
        defer self.in_force_update = false;
        _ = self.webProcessProxy().connection().waitForAndDispatchImmediately(self.identifier(), 500);
        return self.backing_store != null;
    }

    fn incorporateUpdate(self: *DrawingAreaProxyCoordinatedGraphics, update_info: UpdateInfo) !void {
        std.debug.assert(!self.isInAcceleratedCompositingMode());

        if (update_info.update_rect_bounds.isEmpty())
            return;

        if (self.backing_store == null or !self.backing_store.?.size().eql(update_info.view_size) or self.backing_store.?.deviceScaleFactor() != update_info.device_scale_factor) {
            if (self.backing_store) |*backing_store|
                backing_store.deinit();
            self.backing_store = BackingStore.init(self.allocator, update_info.view_size, update_info.device_scale_factor);
        }

        if (self.in_force_update) {
            try self.backing_store.?.incorporateUpdate(update_info);
            return;
        }

        const page = self.page() orelse return;
        var damage_region = Region.init(self.allocator);
        defer damage_region.deinit();

        if (update_info.scroll_rect.isEmpty()) {
            for (update_info.update_rects) |rect|
                try damage_region.unite(rect);
        } else {
            try damage_region.assignRect(.{ .origin = .{}, .size = page.viewSize() });
        }

        try self.backing_store.?.incorporateUpdate(update_info);
        try page.setViewNeedsDisplay(&damage_region);
    }

    fn displayNominalFramesPerSecond(self: *DrawingAreaProxyCoordinatedGraphics) ?FramesPerSecond {
        if (self.page()) |page| {
            if (page.displayID()) |display_id|
                return page.legacyMainFrameProcess().nominalFramesPerSecondForDisplay(display_id);
        }
        return null;
    }

    fn sizeDidChange(self: *DrawingAreaProxyCoordinatedGraphics) void {
        const page = self.page() orelse return;
        if (!page.hasRunningProcess())
            return;

        if (self.is_waiting_for_did_update_geometry)
            return;

        self.sendUpdateGeometry();
    }

    fn deviceScaleFactorDidChange(self: *DrawingAreaProxyCoordinatedGraphics, completion_handler: CompletionHandler) void {
        if (self.page() == null) {
            completion_handler();
            return;
        }
        completion_handler();
    }

    fn setBackingStoreIsDiscardable(self: *DrawingAreaProxyCoordinatedGraphics, is_backing_store_discardable: bool) void {
        if (self.is_backing_store_discardable == is_backing_store_discardable)
            return;

        self.is_backing_store_discardable = is_backing_store_discardable;
        if (self.is_backing_store_discardable)
            self.discardBackingStoreSoon()
        else {
            self.discard_backing_store_timer.stop();
            self.discard_backing_store_deadline = null;
        }
    }

    fn adjustTransientZoom(_: *DrawingAreaProxyCoordinatedGraphics, _: f64, _: FloatPoint, _: FloatPoint) void {}

    fn commitTransientZoom(_: *DrawingAreaProxyCoordinatedGraphics, _: f64, _: FloatPoint) void {}

    fn enterAcceleratedCompositingModeWithIdentifier(self: *DrawingAreaProxyCoordinatedGraphics, _: u64, layer_tree_context: LayerTreeContext) void {
        self.enterAcceleratedCompositingMode(layer_tree_context);
    }

    fn update(self: *DrawingAreaProxyCoordinatedGraphics, _: u64, update_info: UpdateInfo) !void {
        if (self.is_waiting_for_did_update_geometry and !update_info.view_size.eql(self.last_sent_size)) {
            _ = MonotonicTime.now();
            return;
        }

        try self.incorporateUpdate(update_info);

        if (!self.is_waiting_for_did_update_geometry)
            _ = MonotonicTime.now();
    }

    fn exitAcceleratedCompositingModeWithUpdate(self: *DrawingAreaProxyCoordinatedGraphics, _: u64, update_info: UpdateInfo) !void {
        self.exitAcceleratedCompositingMode();
        try self.incorporateUpdate(update_info);
    }

    fn updateAcceleratedCompositingModeWithIdentifier(self: *DrawingAreaProxyCoordinatedGraphics, _: u64, layer_tree_context: LayerTreeContext) void {
        self.updateAcceleratedCompositingMode(layer_tree_context);
    }

    fn alwaysUseCompositing(self: *DrawingAreaProxyCoordinatedGraphics) bool {
        const page = self.page() orelse return false;
        return page.preferences().acceleratedCompositingEnabled() and page.preferences().forceCompositingMode();
    }

    fn enterAcceleratedCompositingMode(self: *DrawingAreaProxyCoordinatedGraphics, layer_tree_context: LayerTreeContext) void {
        if (self.isInAcceleratedCompositingMode()) {
            self.updateAcceleratedCompositingMode(layer_tree_context);
            return;
        }

        if (self.backing_store) |*backing_store|
            backing_store.deinit();
        self.backing_store = null;
        self.layer_tree_context = layer_tree_context;
        if (self.page()) |page|
            page.enterAcceleratedCompositingMode(layer_tree_context);
    }

    fn exitAcceleratedCompositingMode(self: *DrawingAreaProxyCoordinatedGraphics) void {
        std.debug.assert(self.isInAcceleratedCompositingMode());

        self.layer_tree_context = .{};
        if (self.page()) |page|
            page.exitAcceleratedCompositingMode();
    }

    fn updateAcceleratedCompositingMode(self: *DrawingAreaProxyCoordinatedGraphics, layer_tree_context: LayerTreeContext) void {
        std.debug.assert(self.isInAcceleratedCompositingMode());

        self.layer_tree_context = layer_tree_context;
        if (self.page()) |page|
            page.updateAcceleratedCompositingMode(layer_tree_context);
    }

    fn dispatchPresentationCallbacksAfterFlushingLayers(_: *DrawingAreaProxyCoordinatedGraphics, connection: *Connection, callback_ids: []const AsyncReplyID) void {
        for (callback_ids) |callback_id| {
            if (connection.takeAsyncReplyHandler(callback_id)) |callback|
                callback(null, null);
        }
    }

    fn sendUpdateGeometry(self: *DrawingAreaProxyCoordinatedGraphics) void {
        std.debug.assert(!self.is_waiting_for_did_update_geometry);
        self.last_sent_size = self.size();
        self.is_waiting_for_did_update_geometry = true;
        self.didUpdateGeometry();
    }

    fn didUpdateGeometry(self: *DrawingAreaProxyCoordinatedGraphics) void {
        std.debug.assert(self.is_waiting_for_did_update_geometry);

        self.is_waiting_for_did_update_geometry = false;

        if (!self.last_sent_size.eql(self.size()))
            self.sendUpdateGeometry();
    }

    fn discardBackingStoreSoon(self: *DrawingAreaProxyCoordinatedGraphics) void {
        if (self.backing_store == null or !self.is_backing_store_discardable or self.discard_backing_store_timer.isActive())
            return;

        self.discard_backing_store_timer.startOneShot(10);
        self.discard_backing_store_deadline = std.time.nanoTimestamp() + 10 * std.time.ns_per_s;
    }

    fn discardBackingStore(self: *DrawingAreaProxyCoordinatedGraphics) void {
        if (self.backing_store) |*backing_store|
            backing_store.deinit()
        else
            return;

        self.backing_store = null;
    }

    fn dispatchAfterEnsuringDrawing(self: *DrawingAreaProxyCoordinatedGraphics, callback_function: CompletionHandler) void {
        const page = self.page() orelse {
            callback_function();
            return;
        };
        if (!page.hasRunningProcess()) {
            callback_function();
            return;
        }

        if (self.drawing_monitor == null)
            self.drawing_monitor = DrawingMonitor.init(page);
        self.drawing_monitor.?.start(callback_function);
    }
};

pub fn main() void {
    _ = DrawingAreaProxyCoordinatedGraphics;
}
